INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Serviceanfragen > Kundenzufriedenheit
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Kundenzufriedenheit bei Serviceanfragen ausschließlich von der technischen Lösung abhängig?', 2, '[{"text": "Nein", "correct": true, "because": "Kommunikation und Zeit spielen ebenfalls eine Rolle"}, {"text": "Ja", "correct": false, "because": "Mehr als nur Technik beeinflusst Zufriedenheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine schnelle Bearbeitung von Serviceanfragen die Kundenzufriedenheit erhöhen?', 2, '[{"text": "Ja", "correct": true, "because": "Zeit ist ein wichtiger Faktor für Kunden"}, {"text": "Nein", "correct": false, "because": "Schnelligkeit wirkt sich positiv aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Kunden immer direkt über den Fortschritt ihrer Serviceanfrage informiert werden, um zufrieden zu sein?', 2, '[{"text": "Nein", "correct": true, "because": "Information ist hilfreich, aber nicht immer zwingend"}, {"text": "Ja", "correct": false, "because": "Zufriedenheit hängt von mehreren Faktoren ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Können wiederholte Probleme mit Serviceanfragen die Kundenzufriedenheit senken?', 2, '[{"text": "Ja", "correct": true, "because": "Wiederholungen signalisieren mangelnde Qualität"}, {"text": "Nein", "correct": false, "because": "Kunden erwarten dauerhafte Lösungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Kundenzufriedenheit unabhängig von der Freundlichkeit des Supports?', 2, '[{"text": "Nein", "correct": true, "because": "Freundlichkeit beeinflusst das Erlebnis"}, {"text": "Ja", "correct": false, "because": "Kunden schätzen positive Interaktionen"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor hat den größten Einfluss auf die Kundenzufriedenheit bei Serviceanfragen?', 3, '[{"text": "Qualität der Problemlösung", "correct": true, "because": "Lösung ist Kern der Anfrage"}, {"text": "Farbe der Benutzeroberfläche", "correct": false, "because": "Irrelevant für Service"}, {"text": "Anzahl der Supportmitarbeiter", "correct": false, "because": "Weniger entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird oft verwendet, um die Kundenzufriedenheit nach einer Serviceanfrage zu messen?', 2, '[{"text": "Umfragen", "correct": true, "because": "Direktes Feedback von Kunden"}, {"text": "Systemprotokolle", "correct": false, "because": "Technische Daten, kein Feedback"}, {"text": "Zufällige Schätzung", "correct": false, "because": "Unzuverlässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Kundenzufriedenheit im Kontext von Serviceanfragen?', 2, '[{"text": "Vertrauen in den Service aufbauen", "correct": true, "because": "Langfristige Beziehung fördern"}, {"text": "Kosten der Bearbeitung senken", "correct": false, "because": "Nebenaspekt"}, {"text": "Anzahl der Anfragen erhöhen", "correct": false, "because": "Nicht gewünscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann die Kundenzufriedenheit bei der Bearbeitung einer Serviceanfrage mindern?', 3, '[{"text": "Mangelnde Kommunikation", "correct": true, "because": "Kunden fühlen sich ignoriert"}, {"text": "Schnelle Antwortzeit", "correct": false, "because": "Positiv, kein Fehler"}, {"text": "Automatische Lösung", "correct": false, "because": "Nicht zwangsläufig negativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten des Supports trägt am meisten zur Kundenzufriedenheit bei?', 2, '[{"text": "Empathisches Auftreten", "correct": true, "because": "Kunden fühlen sich verstanden"}, {"text": "Technischer Jargon", "correct": false, "because": "Kann verwirrend wirken"}, {"text": "Langsame Reaktion", "correct": false, "because": "Frustriert Kunden"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Kundenzufriedenheit bei Serviceanfragen?', 4, '[{"text": "Bearbeitungszeit", "correct": true, "because": "Schnelligkeit ist wichtig"}, {"text": "Kommunikation", "correct": true, "because": "Klarheit schafft Vertrauen"}, {"text": "Lösungsqualität", "correct": true, "because": "Entscheidend für Erfolg"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant für Kunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen können die Kundenzufriedenheit steigern?', 3, '[{"text": "Regelmäßige Updates", "correct": true, "because": "Informiert Kunden"}, {"text": "Kompetente Antworten", "correct": true, "because": "Zeigt Fachwissen"}, {"text": "Proaktive Problemlösung", "correct": true, "because": "Vermeidet Wiederholungen"}, {"text": "Längere Wartezeiten", "correct": false, "because": "Mindert Zufriedenheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können die Kundenzufriedenheit bei Serviceanfragen senken?', 4, '[{"text": "Langsame Reaktionszeiten", "correct": true, "because": "Frustriert Kunden"}, {"text": "Unklare Kommunikation", "correct": true, "because": "Verwirrt Kunden"}, {"text": "Ungeklärte Probleme", "correct": true, "because": "Lösung bleibt aus"}, {"text": "Schnelle Problemlösung", "correct": false, "because": "Kein Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden helfen, die Kundenzufriedenheit zu bewerten?', 3, '[{"text": "Feedback-Formulare", "correct": true, "because": "Direktes Kundenfeedback"}, {"text": "Net Promoter Score (NPS)", "correct": true, "because": "Misst Weiterempfehlung"}, {"text": "Kundengespräche", "correct": true, "because": "Persönliche Einsichten"}, {"text": "Hardwaretests", "correct": false, "because": "Technisch, nicht kundenbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften eines Supports tragen zur Kundenzufriedenheit bei?', 3, '[{"text": "Freundlichkeit", "correct": true, "because": "Positive Erfahrung"}, {"text": "Kompetenz", "correct": true, "because": "Vertrauen in Lösung"}, {"text": "Transparenz", "correct": true, "because": "Klarheit im Prozess"}, {"text": "Technische Komplexität", "correct": false, "because": "Kann abschrecken"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Kundenzufriedenheit kann durch klare Kommunikation gesteigert werden. b) Die Bearbeitungszeit hat keinen Einfluss auf die Zufriedenheit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kommunikation ja, Zeit relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Wiederholte Probleme mindern die Kundenzufriedenheit. b) Kundenfeedback ist für die Zufriedenheit irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wiederholungen ja, Feedback wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Empathie im Support kann die Kundenzufriedenheit erhöhen. b) Alle Kunden bewerten Zufriedenheit gleich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Empathie ja, Bewertung individuell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine schnelle Lösung trägt zur Kundenzufriedenheit bei. b) Die Qualität der Lösung ist für Kunden unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schnelligkeit ja, Qualität entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Transparenz im Bearbeitungsprozess fördert die Kundenzufriedenheit. b) Kunden erwarten keine Rückmeldung zu ihren Anfragen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Transparenz ja, Rückmeldung gewünscht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

